def looks_like_bad_yaml(path):
    try:
        data = Path(path).read_text(encoding='utf-8', errors='replace')
    except FileNotFoundError:
        raise
    except Exception:
        return False
    # The common failure mode in tests and in observed behavior: an unfinished
    # flow sequence such as "gui: [". This deliberately remains permissive for
    # normal simple YAML config snippets.
    for line in data.splitlines():
        s = line.strip()
        if s.endswith('[') or s.endswith('{'):
            return True
    if data.count('[') > data.count(']'):
        return True
    if data.count('{') > data.count('}'):
