    lines.append("╰" + "─" * 29 + "╯╰" + "─" * 54 + "╯")
    lines.append("Confirm: <enter> | Close/Cancel: <esc> | Quit: q | Menu: ?        Donate Ask Question " + VERSION)
    sys.stdout.write("\x1b[?1049h\x1b[?25l\x1b[H\x1b[2J")
