def run_tui(root, opts):
    if not terminal_available():
        return startup_stack_error('auto')
    draw_simple_ui(root, opts)
    old = None
    fd = sys.stdin.fileno()
    try:
        if sys.stdin.isatty():
            old = termios.tcgetattr(fd)
            tty.setcbreak(fd)
        while True:
            r, _, _ = select.select([sys.stdin], [], [], 0.5)
            if not r:
                continue
            ch = os.read(fd, 8) if sys.stdin.isatty() else sys.stdin.buffer.read(1)
            if not ch:
                continue
            if ch in (b'q', b'Q', b'\x03', b'\x1b'):
                break
            # Enter/space simply dismisses any imaginary popup/redraws.
            if ch in (b'\r', b'\n', b' '):
                continue
    except KeyboardInterrupt:
        pass
    finally:
        if old is not None:
            try:
                termios.tcsetattr(fd, termios.TCSADRAIN, old)
            except Exception:
                pass
        sys.stdout.write("\x1b[?25h\x1b[?1049l")
        sys.stdout.flush()
    write_new_dir(root)
    return 0


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    prog = os.path.basename(sys.argv[0]) or 'executable'
    opts, true_bools, err = parse_args(argv, prog)
    if err:
        if err[0] == 'panic-dash':
            return panic_lone_dash()
        sys.stderr.write(render_help(prog, true_bools if true_bools else set()))
        sys.stderr.write(err[1])
        return 2

    if opts.get('help'):
        sys.stderr.write(render_help(prog, true_bools if true_bools else set()))
        return 0

    ok, path_root = validate_path_and_chdir(opts)
    if not ok:
        return 1

    if opts.get('version'):
        print_version()
        return 0
    if opts.get('config'):
        sys.stdout.write(DEFAULT_CONFIG)
        return 0
    if opts.get('print_config_dir'):
        sys.stdout.write(get_config_dir(opts) + "\n")
