def parse_args(argv, prog):
    opts = {
        'help': False, 'version': False, 'debug': False, 'logs': False,
        'profile': False, 'config': False, 'print_config_dir': False,
        'path': '', 'filter': '', 'use_config_dir': '', 'work_tree': '',
        'git_dir': '', 'use_config_file': '', 'screen_mode': '',
    }
    true_bools = set()
    positionals = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == '-':
            return None, None, ('panic-dash', None)
        if arg == '--':
            break
        if arg.startswith('-') and arg != '':
            stripped = arg.lstrip('-')
            if '=' in stripped:
                name, value = stripped.split('=', 1)
                if name in VALUE_FLAGS:
                    key = VALUE_FLAGS[name]
                    opts[key] = value
                elif name in BOOL_FLAGS and name not in ('h', 'help'):
                    key = BOOL_FLAGS[name]
                    val = parse_bool_value(value)
                    opts[key] = val
                    if val:
                        true_bools.add(key)
                else:
                    return opts, true_bools, ('parse-error', f"Unknown arguments supplied:  {stripped}\n")
            else:
                name = stripped
                if name in VALUE_FLAGS:
                    if i + 1 >= len(argv):
                        return opts, true_bools, ('parse-error', f"Expected a following arg for flag {name}, but it did not exist.\n")
                    opts[VALUE_FLAGS[name]] = argv[i+1]
                    i += 1
                elif name in BOOL_FLAGS:
                    key = BOOL_FLAGS[name]
                    opts[key] = True
                    if key != 'help':
                        true_bools.add(key)
                else:
                    if i + 1 >= len(argv):
                        return opts, true_bools, ('parse-error', f"Expected a following arg for flag {name}, but it did not exist.\n")
                    nxt = argv[i+1].lstrip('-')
                    return opts, true_bools, ('parse-error', f"Unknown arguments supplied:  {name} {nxt}\n")
        else:
            positionals.append(arg)
        i += 1
    if len(positionals) > 1:
        return opts, true_bools, ('parse-error', f"Unexpected argument: {positionals[1]}\n")
    opts['git_arg'] = positionals[0] if positionals else ''
    return opts, true_bools, None


