def tail_logs(opts):
    logdir = get_log_dir(opts)
    try:
        os.makedirs(logdir, exist_ok=True)
    except Exception:
        pass
    logfile = os.path.join(logdir, 'development.log')
    sys.stdout.write(f"Tailing log file {logfile}\n\n")
    sys.stdout.flush()
    if not os.path.exists(logfile):
        log_error("Log file does not exist. Run `lazygit --debug` first to create the log file")
        return 1
    try:
        with open(logfile, 'r', encoding='utf-8', errors='replace') as f:
            data = f.read()
            if data:
                sys.stdout.write(data)
                if not data.endswith('\n'):
                    sys.stdout.write('\n')
                sys.stdout.flush()
            while True:
                chunk = f.read()
                if chunk:
                    sys.stdout.write(chunk)
                    sys.stdout.flush()
                time.sleep(0.2)
    except KeyboardInterrupt:
        return 0


def looks_like_bad_yaml(path):
    try:
        data = Path(path).read_text(encoding='utf-8', errors='replace')
    except FileNotFoundError:
        raise
    except Exception:
        return False
    # The common failure mode in tests and in observed behavior: an unfinished
    # flow sequence such as "gui: [". This deliberately remains permissive for
    # normal simple YAML config snippets.
    for line in data.splitlines():
        s = line.strip()
        if s.endswith('[') or s.endswith('{'):
            return True
    if data.count('[') > data.count(']'):
        return True
    if data.count('{') > data.count('}'):
        return True
    return False


def validate_yaml_file(path):
    if not os.path.exists(path):
        log_error(f"stat {path}: no such file or directory")
        return False
    if looks_like_bad_yaml(path):
        log_error("failed to parse YAML: yaml: line 1: did not find expected node content")
        return False
    return True


def validate_startup_configs(opts):
    ucf = opts.get('use_config_file') or ''
    if ucf:
        for p in ucf.split(','):
            if not validate_yaml_file(p):
                return False
    cfg_file = os.path.join(get_config_dir(opts), 'config.yml')
    if os.path.exists(cfg_file):
        if not validate_yaml_file(cfg_file):
            return False
    return True


def abs_clean(path):
    return os.path.abspath(os.path.normpath(path))


def validate_path_and_chdir(opts):
    p = opts.get('path') or ''
    if p:
        ap = abs_clean(p)
        if not os.path.isdir(os.path.join(ap, '.git')):
            log_error(f"{ap} is not a valid git repository.")
            return False, None
        try:
            os.chdir(ap)
        except Exception:
            pass
        return True, ap
    wt = opts.get('work_tree') or ''
    if wt:
        awt = abs_clean(wt)
        if not os.path.isdir(awt):
            log_error(f"Failed to change directory to {awt}: chdir {awt}: no such file or directory")
            return False, None
        try:
            os.chdir(awt)
        except Exception:
            pass
    return True, None


