    sys.stderr.write(
        f"{now_prefix()} An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n"
        f"{detail}\n"
        "/workspace/pkg/app/app.go:55 (0xc91c3f)\n"
