    lines = []
    lines.append("╭─[1]─Status" + "─" * 20 + "╮╭─[0]─Unstaged changes" + "─" * 24 + "╮")
    lines.append(f"│ {os.path.basename(root) or root} → {branch}".ljust(32) + "││" + ("No changes" if not status else status[0]).ljust(45) + "│")
