    else:
        lines.append("│ No changed files".ljust(69) + "│")
    lines.append("╰" + "─" * 68 + "╯")
    lines.append("╭─[3]─Local Branches" + "─" * 20 + "╮╭─[4]─Commits" + "─" * 30 + "╮")
    lines.append(("│ * " + branch).ljust(43) + "││" + (commits[0] if commits else "No commits").ljust(42) + "│")
    for c in commits[1:5]:
